<?php $title='Messages';require __DIR__.'/_layout.php';if(!can_manage('messages'))exit('Forbidden');if(isset($_GET['read']))db()->prepare("UPDATE contact_messages SET status='read' WHERE id=?")->execute([(int)$_GET['read']]);$rows=db()->query("SELECT * FROM contact_messages ORDER BY created_at DESC")->fetchAll();?><h1>Contact Messages</h1><table class="table"><tr><th>From</th><th>Subject</th><th>Message</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?> &lt;<?=e($r['email'])?>&gt;</td><td><?=e($r['subject'])?></td><td><?=e(mb_strimwidth($r['message'],0,120,'…'))?></td><td><?=e($r['status'])?> <a href="?read=<?=$r['id']?>">mark read</a></td></tr><?php endforeach;?></table><?php require __DIR__.'/_footer.php';?>